       FROM clock_stops cs JOIN users o ON o.id = cs.owner_user_id JOIN users sb ON sb.id = cs.started_by LEFT JOIN users eb ON eb.id = cs.ended_by
       WHERE cs.job_id = ? ORDER BY cs.started_at`,
