2	import { tx } from '../db/db.ts';
3	import { type Actor, requireApproval, requireCap } from '../auth/policy.ts';
4	import { audit, notify } from './audit.ts';
5	import { clock } from '../lib/clock.ts';
6	import { ConflictError, DomainError, ForbiddenError, NotFoundError } from '../lib/errors.ts';
7	import { Form } from '../lib/form.ts';
8	import { nextRef } from '../lib/refs.ts';
9	import { getAttendance } from './scheduling.ts';
10	
11	export const STOCK_STATES = ['available', 'reserved', 'picked', 'quarantined', 'return_pending', 'evidence_hold', 'obsolete'] as const;
12	export type StockState = (typeof STOCK_STATES)[number];
13	export type OwnerType = 'frostline' | 'customer' | 'job';
14	export const STATE_LABEL: Record<StockState, string> = {
15	  available: 'Available',
16	  reserved: 'Reserved',
17	  picked: 'Picked',
18	  quarantined: 'Quarantined',
19	  return_pending: 'Return pending assessment',
20	  evidence_hold: 'Evidence hold',
21	  obsolete: 'Obsolete',
22	};
23	export const RECEIPT_CONDITIONS = ['good', 'damaged', 'incorrect', 'uncertain'] as const;
24	export const RETURN_OUTCOMES = ['unused', 'opened', 'damaged', 'contaminated', 'suspect', 'customer_owned', 'warranty_return', 'disposal'] as const;
25	export const RETURN_OUTCOME_LABEL: Record<(typeof RETURN_OUTCOMES)[number], string> = {
26	  unused: 'Unused — return to available',
27	  opened: 'Opened — quarantine for inspection',
28	  damaged: 'Damaged — quarantine',
29	  contaminated: 'Contaminated — quarantine',
30	  suspect: 'Suspect — quarantine',
31	  customer_owned: 'Customer-owned — hold for customer',
32	  warranty_return: 'Warranty return — evidence hold',
33	  disposal: 'Disposal (authorised)',
34	};
35	
36	interface BalanceKey {
37	  item_id: number;
38	  location_id: number;
39	  state: StockState;
40	  owner_type?: OwnerType;
41	  owner_ref?: number;
42	}
43	
44	/**
45	 * Atomic conditional decrement: succeeds only if enough quantity exists in exactly this
46	 * bucket at the moment of the write. Combined with BEGIN IMMEDIATE and the qty >= 0 CHECK,
47	 * concurrent issues/reservations can never drive legitimate availability negative (AC-060-02).
48	 */
49	function take(db: DB, k: BalanceKey, qty: number, what = 'stock') {
50	  const r = db
51	    .prepare(`UPDATE stock_balances SET qty = qty - ? WHERE item_id = ? AND location_id = ? AND state = ? AND owner_type = ? AND owner_ref = ? AND qty >= ?`)
52	    .run(qty, k.item_id, k.location_id, k.state, k.owner_type ?? 'frostline', k.owner_ref ?? 0, qty);
53	  if (r.changes !== 1) {
54	    const have = bucketQty(db, k);
55	    throw new ConflictError(`Not enough ${what}: ${have} ${STATE_LABEL[k.state].toLowerCase()} at this location, ${qty} requested. Someone may have just used it — refresh and re-check.`);
56	  }
57	}
58	
59	function put(db: DB, k: BalanceKey, qty: number) {
60	  db.prepare(
61	    `INSERT INTO stock_balances (item_id, location_id, state, owner_type, owner_ref, qty) VALUES (?, ?, ?, ?, ?, ?)
62	     ON CONFLICT (item_id, location_id, state, owner_type, owner_ref) DO UPDATE SET qty = qty + excluded.qty`,
63	  ).run(k.item_id, k.location_id, k.state, k.owner_type ?? 'frostline', k.owner_ref ?? 0, qty);
64	}
65	
66	function bucketQty(db: DB, k: BalanceKey): number {
67	  return (
68	    (db
69	      .prepare(`SELECT qty FROM stock_balances WHERE item_id = ? AND location_id = ? AND state = ? AND owner_type = ? AND owner_ref = ?`)
70	      .get(k.item_id, k.location_id, k.state, k.owner_type ?? 'frostline', k.owner_ref ?? 0) as { qty: number } | undefined)?.qty ?? 0
71	  );
72	}
73	
