87	  receipt_line_id?: number | null;
88	  recipient?: string | null;
89	  serial_batch?: string | null;
90	  reason?: string | null;
91	  idem_key?: string | null;
92	}
93	
94	function movement(db: DB, actor: Actor, m: MovementInput): number {
95	  const r = db
96	    .prepare(
97	      `INSERT INTO stock_movements (movement_type, item_id, qty, from_location_id, from_state, to_location_id, to_state, owner_type, owner_ref, job_id, attendance_id,
98	         reservation_id, receipt_line_id, recipient, serial_batch, reason, actor_id, at, idem_key)
99	       VALUES (@movement_type, @item_id, @qty, @from_location_id, @from_state, @to_location_id, @to_state, @owner_type, @owner_ref, @job_id, @attendance_id,
100	         @reservation_id, @receipt_line_id, @recipient, @serial_batch, @reason, @actor, @at, @idem_key)`,
101	    )
102	    .run({
103	      from_location_id: null,
104	      from_state: null,
105	      to_location_id: null,
