  const urgent = db.prepare(`SELECT ${JOB_COLS} ${JOB_FROM} WHERE j.op_status IN ${OPEN_IN} AND j.priority IN ('P1','P2') ORDER BY j.priority, j.received_at`).all() as JobRow[];
