    // Chester AHU (released quoted works): motor reserved; readiness partly confirmed.
    at(-60 * 24 * 10, () =>
      inv.receiveGoods(db, U.mick, {
        supplier: 'Motor Supplies North',
        po_ref: 'PO-31802',
        location_id: String(LOC.WH),
        line_item_id: [String(I['MTR-AHU-4KW'])],
        line_qty_received: ['1'],
