input.content:
/* FrostLine operations CRM — dense desktop tables, touch-friendly field views.
   Brand cues (colour, name) taken from the public website; layout is application, not marketing. */

:root {
  --primary: #1a3a5c;
  --primary-light: #2a5a8c;
  --accent: #3a8fb7;
  --accent-warm: #e87c3e;
  --dark: #0f2237;
  --ink: #1a1a2e;
  --ink-2: #4a4a5a;
  --ink-3: #6f6f80;
  --line: #d9dce3;
  --line-2: #eceef2;
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --danger: #b4231f;
  --danger-bg: #fdeceb;
  --warn: #8a5300;
  --warn-bg: #fdf3e3;
  --ok: #1f6b3f;
  --ok-bg: #eaf5ee;
  --info: #1d5c80;
  --info-bg: #e9f3f9;
  --radius: 6px;
  --shadow: 0 1px 2px rgba(15, 34, 55, 0.08), 0 2px 8px rgba(15, 34, 55, 0.06);
  --shadow-lg: 0 8px 28px rgba(15, 34, 55, 0.18);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }

html { font-size: 16px; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.45;
  font-size: 14px;
}

a { color: var(--primary-light); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3, h4 { line-height: 1.25; font-weight: 600; color: var(--dark); }
h1 { font-size: 1.35rem; }
h2 { font-size: 1.05rem; }
h3 { font-size: 0.95rem; }
h4 { font-size: 0.85rem; }
small { font-size: 0.8125rem; }
code, .mono { font-family: var(--mono); font-size: 0.85em; }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

.skip { position: absolute; left: -9999px; top: 0; background: var(--surface); padding: 8px 12px; z-index: 100; }
.skip:focus { left: 8px; top: 8px; }

/* ---------------------------------------------------------------- app frame */
.app { min-height: 100vh; display: flex; flex-direction: column; }

.topbar {
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  min-height: 52px;
  position: sticky;
  top: 0;
  z-index: 30;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 600; letter-spacing: 0.01em; color: #fff; flex: 0 0 auto; }
.brand:hover { text-decoration: none; }
.brand svg { width: 26px; height: 26px; }
.brand span { font-size: 0.95rem; }
.brand b { font-weight: 700; }
.brand-sub { color: #b9cde0; font-weight: 400; font-size: 0.78rem; display: none; }
@media (min-width: 1100px) { .brand-sub { display: inline; } }

.topsearch { flex: 1 1 auto; max-width: 420px; display: flex; }
.topsearch input {
  width: 100%;
  border: 1px solid rgba(255,255,255,0.28);
  background: rgba(255,255,255,0.14);
  color: #fff;
  padding: 6px 10px;
  border-radius: var(--radius);
  font: inherit;
  font-size: 0.875rem;
}
.topsearch input::placeholder { color: #cfe0ee; }
.topsearch input:focus { background: #fff; color: var(--ink); }
.topsearch input:focus::placeholder { color: var(--ink-3); }

.topright { margin-left: auto; display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.whoami { text-align: right; line-height: 1.2; display: none; }
@media (min-width: 720px) { .whoami { display: block; } }
.whoami b { display: block; font-size: 0.8125rem; }
.whoami small { color: #b9cde0; }
.bell { position: relative; color: #fff; display: inline-flex; align-items: center; padding: 4px; }
.bell .dot {
  position: absolute; top: 0; right: 0;
  background: var(--accent-warm); color: #fff; font-size: 0.65rem; font-weight: 700;
  min-width: 16px; height: 16px; border-radius: 8px; display: grid; place-items: center; padding: 0 3px;
}
.logout { color: #cfe0ee; font-size: 0.8125rem; }

nav.mainnav { background: var(--dark); display: flex; gap: 2px; padding: 0 8px; overflow-x: auto; position: sticky; top: 52px; z-index: 29; scrollbar-width: none; }
nav.mainnav::-webkit-scrollbar { display: none; }
nav.mainnav a {
  color: #cfe0ee; padding: 9px 12px; font-size: 0.8125rem; font-weight: 500; white-space: nowrap;
  border-bottom: 3px solid transparent;
}
nav.mainnav a:hover { color: #fff; text-decoration: none; background: rgba(255,255,255,0.05); }
nav.mainnav a[aria-current='page'] { color: #fff; border-bottom-color: var(--accent); }

main { flex: 1 1 auto; padding: 16px; width: 100%; max-width: 1560px; margin: 0 auto; }
main.narrow { max-width: 820px; }

.pagehead { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px; margin-bottom: 14px; }
.pagehead .grow { flex: 1 1 320px; min-width: 0; }
.pagehead h1 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.crumbs { font-size: 0.8125rem; color: var(--ink-3); margin-bottom: 4px; }
.crumbs a { color: var(--ink-2); }
.subtle { color: var(--ink-3); }
.pagehead .actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* ---------------------------------------------------------------- surfaces */
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 14px;
  overflow: hidden;
}
.card > header {
  padding: 9px 12px;
  border-bottom: 1px solid var(--line-2);
  background: var(--surface-2);
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
}
.card > header h2, .card > header h3 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-2); }
.card > header .spacer { margin-left: auto; }
.card .body { padding: 12px; }
.card .body.tight { padding: 0; }
.card .foot { padding: 9px 12px; border-top: 1px solid var(--line-2); background: var(--surface-2); }
.definition { font-size: 0.78rem; color: var(--ink-3); padding: 8px 12px; border-top: 1px dashed var(--line); background: var(--surface-2); }

.grid { display: grid; gap: 14px; }
.grid.cols2 { grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); }
.grid.cols3 { grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); }
.grid.split { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
@media (max-width: 1000px) { .grid.split { grid-template-columns: 1fr; } }

/* ---------------------------------------------------------------- tables */
.tablewrap { overflow-x: auto; }
table.data { width: 100%; border-collapse: collapse; font-size: 0.8125rem; }
table.data th, table.data td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line-2); vertical-align: top; }
table.data th {
  font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-3);
  background: var(--surface-2); position: sticky; top: 0; font-weight: 600; white-space: nowrap;
}
table.data tbody tr:hover { background: #f7fafd; }
table.data tr.clickable { cursor: pointer; }
table.data td.num, table.data th.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data td.nowrap, table.data th.nowrap { white-space: nowrap; }
table.data .rowtitle { font-weight: 600; color: var(--dark); }
table.data tr.rowdanger { background: var(--danger-bg); }
table.data tr.rowwarn { background: var(--warn-bg); }
.tfoot { padding: 8px 12px; font-size: 0.8125rem; color: var(--ink-3); display: flex; gap: 10px; align-items: center; }

dl.def { display: grid; grid-template-columns: minmax(130px, max-content) 1fr; gap: 4px 14px; font-size: 0.8125rem; margin: 0; }
dl.def dt { color: var(--ink-3); }
dl.def dd { margin: 0; color: var(--ink); overflow-wrap: anywhere; }
dl.def.stack { grid-template-columns: 1fr; gap: 2px; }
dl.def.stack dd { margin-bottom: 8px; }

.kv { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 0.8125rem; }
.kv > div { display: flex; gap: 6px; }
.kv b { color: var(--ink-3); font-weight: 500; }

/* ---------------------------------------------------------------- chips & badges */
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 1px 7px; border-radius: 10px; font-size: 0.72rem; font-weight: 600;
  background: var(--line-2); color: var(--ink-2); white-space: nowrap; border: 1px solid transparent;
}
.chip.ok { background: var(--ok-bg); color: var(--ok); }
.chip.warn { background: var(--warn-bg); color: var(--warn); }
.chip.danger { background: var(--danger-bg); color: var(--danger); }
.chip.info { background: var(--info-bg); color: var(--info); }
.chip.neutral { background: var(--line-2); color: var(--ink-2); }
.chip.solid-danger { background: var(--danger); color: #fff; }
.chip.p1 { background: var(--danger); color: #fff; }
.chip.p2 { background: #f7dbc9; color: #8a3f0b; }
.chip.p3 { background: var(--info-bg); color: var(--info); }
.chip.p4 { background: var(--line-2); color: var(--ink-2); }
.chip.big { font-size: 0.8125rem; padding: 3px 10px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }

.count { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 1.6rem; color: var(--dark); line-height: 1; }
.count.danger { color: var(--danger); }
.count.warn { color: var(--warn); }
.count.ok { color: var(--ok); }

/* ---------------------------------------------------------------- banners */
.banner { padding: 9px 12px; border-radius: var(--radius); border: 1px solid; font-size: 0.8125rem; margin-bottom: 12px; display: flex; gap: 8px; align-items: flex-start; }
.banner b { display: block; }
.banner.ok { background: var(--ok-bg); border-color: #b6dcc3; color: #14502f; }
.banner.err { background: var(--danger-bg); border-color: #f0b6b3; color: #8d1b18; }
.banner.warn { background: var(--warn-bg); border-color: #edd3a6; color: #6b4100; }
.banner.info { background: var(--info-bg); border-color: #bcd9e8; color: #174c69; }
.banner.security { background: #fff8e8; border-color: #e8cf9a; color: #5e4300; }

.flash { position: sticky; top: 92px; z-index: 20; }

/* ---------------------------------------------------------------- buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: inherit; font-size: 0.8125rem; font-weight: 500;
  padding: 7px 13px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); cursor: pointer; text-decoration: none;
}
.btn:hover { background: var(--surface-2); text-decoration: none; border-color: #c2c7d1; }
.btn:active { transform: translateY(1px); }
.btn.primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-light); border-color: var(--primary-light); }
.btn.accent { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.accent:hover { background: #2f7da2; }
.btn.danger { background: var(--surface); border-color: #e3aeab; color: var(--danger); }
.btn.danger:hover { background: var(--danger-bg); }
.btn.small { font-size: 0.75rem; padding: 3px 8px; min-height: 28px; }
.btn.block { width: 100%; }
.btn:disabled, .btn[aria-disabled='true'] { opacity: 0.5; cursor: not-allowed; }
.btnrow { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.btnrow.end { justify-content: flex-end; }

/* ---------------------------------------------------------------- forms */
form.stack { display: grid; gap: 12px; }
.fields { display: grid; gap: 12px; }
.fields.cols2 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.fields.cols3 { grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); }
.field { display: grid; gap: 4px; min-width: 0; }
.field > label, .field > .lbl { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); }
.field .hint { font-size: 0.75rem; color: var(--ink-3); }
.field .err { font-size: 0.75rem; color: var(--danger); font-weight: 500; }
.field.span2 { grid-column: 1 / -1; }
input[type='text'], input[type='password'], input[type='number'], input[type='date'], input[type='datetime-local'], input[type='time'], input[type='email'], input[type='search'], input[type='file'], select, textarea {
  font: inherit; font-size: 0.875rem;
  padding: 7px 9px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); width: 100%;
}
textarea { min-height: 72px; resize: vertical; line-height: 1.4; }
input:invalid { border-color: #e3aeab; }
.field.bad input, .field.bad select, .field.bad textarea { border-color: var(--danger); background: #fffafa; }
select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%), linear-gradient(135deg, var(--ink-3) 50%, transparent 50%); background-position: calc(100% - 15px) 15px, calc(100% - 10px) 15px; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 28px; }
.check { display: flex; gap: 8px; align-items: flex-start; font-size: 0.8125rem; padding: 3px 0; }
.check input[type='checkbox'], .check input[type='radio'] { width: 18px; height: 18px; margin: 1px 0 0; flex: 0 0 auto; accent-color: var(--primary); }
.check label { cursor: pointer; }
.check .hint { display: block; color: var(--ink-3); font-size: 0.75rem; }
fieldset { border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; }
legend { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); padding: 0 5px; }
.filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; }
.filters .field { min-width: 140px; }
.filters .field.wide { min-width: 260px; flex: 1 1 260px; }

/* disclosure panels used for action forms */
details.drawer { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
details.drawer + details.drawer { margin-top: 8px; }
details.drawer > summary {
  cursor: pointer; padding: 8px 12px; font-size: 0.8125rem; font-weight: 600; color: var(--primary);
  display: flex; align-items: center; gap: 8px; list-style: none; min-height: 38px;
}
details.drawer > summary::-webkit-details-marker { display: none; }
details.drawer > summary::before { content: '▸'; color: var(--ink-3); font-size: 0.8rem; }
details.drawer[open] > summary::before { content: '▾'; }
details.drawer[open] > summary { border-bottom: 1px solid var(--line-2); background: var(--surface-2); }
details.drawer .drawerbody { padding: 12px; }
details.drawer.danger > summary { color: var(--danger); }

.timeline { list-style: none; padding: 0; display: grid; gap: 0; }
.timeline li { display: grid; grid-template-columns: 148px 1fr; gap: 12px; padding: 8px 12px; border-bottom: 1px solid var(--line-2); font-size: 0.8125rem; }
.timeline li:last-child { border-bottom: 0; }
.timeline .when { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.timeline .what b { color: var(--dark); }
.timeline li.superseded .what { text-decoration: line-through; color: var(--ink-3); }
@media (max-width: 620px) { .timeline li { grid-template-columns: 1fr; gap: 2px; } }

.prose { font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.prose.box { background: var(--surface-2); border: 1px solid var(--line-2); border-radius: var(--radius); padding: 9px 11px; }
.empty { padding: 22px 12px; text-align: center; color: var(--ink-3); font-size: 0.8125rem; }
.empty b { display: block; color: var(--ink-2); margin-bottom: 3px; }

/* ---------------------------------------------------------------- schedule board */
.board { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.board table { border-collapse: collapse; width: 100%; min-width: 900px; }
.board th, .board td { border-right: 1px solid var(--line-2); border-bottom: 1px solid var(--line-2); }
.board th { background: var(--surface-2); font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-3); padding: 6px 8px; font-weight: 600; }
.board th.eng { text-align: left; width: 132px; min-width: 132px; position: sticky; left: 0; z-index: 2; }
.board td.eng { position: sticky; left: 0; background: var(--surface); z-index: 1; padding: 6px 8px; font-size: 0.8125rem; font-weight: 600; border-right: 1px solid var(--line); }
.board td.eng small { display: block; font-weight: 400; color: var(--ink-3); }
.board td.slot { padding: 0; position: relative; height: 62px; }
.board .lane { position: relative; height: 100%; }
.slotblock {
  position: absolute; top: 3px; bottom: 3px; border-radius: 4px; padding: 3px 6px; overflow: hidden;
  font-size: 0.72rem; line-height: 1.25; border-left: 3px solid var(--primary); background: #eaf1f8; color: var(--ink);
  box-shadow: 0 1px 2px rgba(0,0,0,0.1); text-decoration: none; display: block;
}
.slotblock:hover { text-decoration: none; box-shadow: var(--shadow-lg); z-index: 5; }
.slotblock b { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slotblock.p1 { border-left-color: var(--danger); background: #fdecea; }
.slotblock.p2 { border-left-color: var(--accent-warm); background: #fdf1e8; }
.slotblock.provisional { background-image: repeating-linear-gradient(45deg, rgba(255,255,255,0.65) 0 6px, transparent 6px 12px); }
.slotblock.submitted { opacity: 0.66; }
.slotblock.cancelled { text-decoration: line-through; opacity: 0.5; }
.weekcell { padding: 4px; vertical-align: top; min-width: 132px; }
.weekcell .slotblock { position: static; margin-bottom: 4px; }
.boardlegend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 0.75rem; color: var(--ink-3); padding: 8px 2px; }

/* ---------------------------------------------------------------- field (mobile) */
.fieldlist { display: grid; gap: 10px; }
.jobcard { display: block; background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--primary); border-radius: var(--radius); padding: 12px; box-shadow: var(--shadow); color: var(--ink); }
.jobcard:hover { text-decoration: none; box-shadow: var(--shadow-lg); }
.jobcard.p1 { border-left-color: var(--danger); }
.jobcard.p2 { border-left-color: var(--accent-warm); }
.jobcard .top { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 4px; }
.jobcard .time { font-weight: 700; font-variant-numeric: tabular-nums; }
.jobcard h3 { font-size: 0.95rem; margin: 2px 0; }
.jobcard .where { font-size: 0.8125rem; color: var(--ink-2); }
.jobcard .sym { font-size: 0.8125rem; color: var(--ink-2); margin-top: 5px; }
.bigactions { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
.bigactions .btn { min-height: 52px; font-size: 0.95rem; font-weight: 600; }
.stepbar { display: flex; gap: 6px; font-size: 0.72rem; color: var(--ink-3); flex-wrap: wrap; margin-bottom: 10px; }
.stepbar span { padding: 2px 8px; border-radius: 10px; background: var(--line-2); }
.stepbar span.done { background: var(--ok-bg); color: var(--ok); font-weight: 600; }
.stepbar span.now { background: var(--primary); color: #fff; font-weight: 600; }

/* AI suggestion panel */
.ai { border: 1px solid #c9dce9; border-radius: var(--radius); background: #f6fafd; margin-bottom: 14px; overflow: hidden; }
.ai > header { background: #e4f0f8; padding: 8px 12px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid #c9dce9; }
.ai > header h3 { font-size: 0.85rem; color: #16506f; }
.ai .body { padding: 12px; }
.ai .suggestion { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.ai .sources { font-size: 0.75rem; color: var(--ink-3); margin-top: 8px; display: flex; gap: 8px; flex-wrap: wrap; }
.ai .note { font-size: 0.75rem; color: #16506f; margin-top: 8px; }
.aibuttons { display: flex; gap: 6px; flex-wrap: wrap; }

/* login */
.loginwrap { min-height: 100vh; display: grid; place-items: center; padding: 20px; background: linear-gradient(160deg, var(--primary) 0%, var(--dark) 100%); }
.loginbox { background: var(--surface); border-radius: 10px; box-shadow: var(--shadow-lg); padding: 26px; width: 100%; max-width: 420px; }
.loginbox .brandrow { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; }
.loginbox .brandrow svg { width: 34px; height: 34px; }
.loginbox h1 { font-size: 1.15rem; }
.demotable { width: 100%; font-size: 0.78rem; border-collapse: collapse; margin-top: 6px; }
.demotable td { padding: 3px 6px; border-bottom: 1px solid var(--line-2); }
.demotable td:first-child { font-family: var(--mono); white-space: nowrap; }

footer.appfoot { padding: 14px 16px; font-size: 0.75rem; color: var(--ink-3); text-align: center; }

/* utility */
.right { text-align: right; }
.nowrap { white-space: nowrap; }
.mono-sm { font-family: var(--mono); font-size: 0.78rem; }
.hidden { display: none !important; }
.mt0 { margin-top: 0; }
.mt1 { margin-top: 8px; }
.mt2 { margin-top: 16px; }
.mb1 { margin-bottom: 8px; }
.strong { font-weight: 600; color: var(--dark); }
.tiny { font-size: 0.75rem; }
.sep { color: var(--line); }

@media (max-width: 700px) {
  main { padding: 10px; }
  .pagehead { gap: 8px; }
  table.data th, table.data td { padding: 6px 8px; }
  dl.def { grid-template-columns: 1fr; gap: 1px; }
  dl.def dd { margin-bottom: 7px; }
  .fields.cols2, .fields.cols3 { grid-template-columns: 1fr; }
  h1 { font-size: 1.15rem; }
}

@media print {
  .topbar, nav.mainnav, .btnrow, details.drawer, footer.appfoot { display: none !important; }
  body { background: #fff; }
  .card { box-shadow: none; break-inside: avoid; }
}

toolu_01QW1bTDGEX66649VVZyknNc.content:
/* FrostLine operations CRM — dense desktop tables, touch-friendly field views.
   Brand cues (colour, name) taken from the public website; layout is application, not marketing. */

:root {
  --primary: #1a3a5c;
  --primary-light: #2a5a8c;
  --accent: #3a8fb7;
  --accent-warm: #e87c3e;
  --dark: #0f2237;
  --ink: #1a1a2e;
  --ink-2: #4a4a5a;
  --ink-3: #6f6f80;
  --line: #d9dce3;
  --line-2: #eceef2;
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --danger: #b4231f;
  --danger-bg: #fdeceb;
  --warn: #8a5300;
  --warn-bg: #fdf3e3;
  --ok: #1f6b3f;
  --ok-bg: #eaf5ee;
  --info: #1d5c80;
  --info-bg: #e9f3f9;
  --radius: 6px;
  --shadow: 0 1px 2px rgba(15, 34, 55, 0.08), 0 2px 8px rgba(15, 34, 55, 0.06);
  --shadow-lg: 0 8px 28px rgba(15, 34, 55, 0.18);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }

html { font-size: 16px; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.45;
  font-size: 14px;
}

a { color: var(--primary-light); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3, h4 { line-height: 1.25; font-weight: 600; color: var(--dark); }
h1 { font-size: 1.35rem; }
h2 { font-size: 1.05rem; }
h3 { font-size: 0.95rem; }
h4 { font-size: 0.85rem; }
small { font-size: 0.8125rem; }
code, .mono { font-family: var(--mono); font-size: 0.85em; }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

.skip { position: absolute; left: -9999px; top: 0; background: var(--surface); padding: 8px 12px; z-index: 100; }
.skip:focus { left: 8px; top: 8px; }

/* ---------------------------------------------------------------- app frame */
.app { min-height: 100vh; display: flex; flex-direction: column; }

.topbar {
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  min-height: 52px;
  position: sticky;
  top: 0;
  z-index: 30;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 600; letter-spacing: 0.01em; color: #fff; flex: 0 0 auto; }
.brand:hover { text-decoration: none; }
.brand svg { width: 26px; height: 26px; }
.brand span { font-size: 0.95rem; }
.brand b { font-weight: 700; }
.brand-sub { color: #b9cde0; font-weight: 400; font-size: 0.78rem; display: none; }
@media (min-width: 1100px) { .brand-sub { display: inline; } }

.topsearch { flex: 1 1 auto; max-width: 420px; display: flex; }
.topsearch input {
  width: 100%;
  border: 1px solid rgba(255,255,255,0.28);
  background: rgba(255,255,255,0.14);
  color: #fff;
  padding: 6px 10px;
  border-radius: var(--radius);
  font: inherit;
  font-size: 0.875rem;
}
.topsearch input::placeholder { color: #cfe0ee; }
.topsearch input:focus { background: #fff; color: var(--ink); }
.topsearch input:focus::placeholder { color: var(--ink-3); }

.topright { margin-left: auto; display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.whoami { text-align: right; line-height: 1.2; display: none; }
@media (min-width: 720px) { .whoami { display: block; } }
.whoami b { display: block; font-size: 0.8125rem; }
.whoami small { color: #b9cde0; }
.bell { position: relative; color: #fff; display: inline-flex; align-items: center; padding: 4px; }
.bell .dot {
  position: absolute; top: 0; right: 0;
  background: var(--accent-warm); color: #fff; font-size: 0.65rem; font-weight: 700;
  min-width: 16px; height: 16px; border-radius: 8px; display: grid; place-items: center; padding: 0 3px;
}
.logout { color: #cfe0ee; font-size: 0.8125rem; }

nav.mainnav { background: var(--dark); display: flex; gap: 2px; padding: 0 8px; overflow-x: auto; position: sticky; top: 52px; z-index: 29; scrollbar-width: none; }
nav.mainnav::-webkit-scrollbar { display: none; }
nav.mainnav a {
  color: #cfe0ee; padding: 9px 12px; font-size: 0.8125rem; font-weight: 500; white-space: nowrap;
  border-bottom: 3px solid transparent;
}
nav.mainnav a:hover { color: #fff; text-decoration: none; background: rgba(255,255,255,0.05); }
nav.mainnav a[aria-current='page'] { color: #fff; border-bottom-color: var(--accent); }

main { flex: 1 1 auto; padding: 16px; width: 100%; max-width: 1560px; margin: 0 auto; }
main.narrow { max-width: 820px; }

.pagehead { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px; margin-bottom: 14px; }
.pagehead .grow { flex: 1 1 320px; min-width: 0; }
.pagehead h1 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.crumbs { font-size: 0.8125rem; color: var(--ink-3); margin-bottom: 4px; }
.crumbs a { color: var(--ink-2); }
.subtle { color: var(--ink-3); }
.pagehead .actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* ---------------------------------------------------------------- surfaces */
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 14px;
  overflow: hidden;
}
.card > header {
  padding: 9px 12px;
  border-bottom: 1px solid var(--line-2);
  background: var(--surface-2);
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
}
.card > header h2, .card > header h3 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-2); }
.card > header .spacer { margin-left: auto; }
.card .body { padding: 12px; }
.card .body.tight { padding: 0; }
.card .foot { padding: 9px 12px; border-top: 1px solid var(--line-2); background: var(--surface-2); }
.definition { font-size: 0.78rem; color: var(--ink-3); padding: 8px 12px; border-top: 1px dashed var(--line); background: var(--surface-2); }

.grid { display: grid; gap: 14px; }
.grid.cols2 { grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); }
.grid.cols3 { grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); }
.grid.split { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
@media (max-width: 1000px) { .grid.split { grid-template-columns: 1fr; } }

/* ---------------------------------------------------------------- tables */
.tablewrap { overflow-x: auto; }
table.data { width: 100%; border-collapse: collapse; font-size: 0.8125rem; }
table.data th, table.data td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line-2); vertical-align: top; }
table.data th {
  font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-3);
  background: var(--surface-2); position: sticky; top: 0; font-weight: 600; white-space: nowrap;
}
table.data tbody tr:hover { background: #f7fafd; }
table.data tr.clickable { cursor: pointer; }
table.data td.num, table.data th.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data td.nowrap, table.data th.nowrap { white-space: nowrap; }
table.data .rowtitle { font-weight: 600; color: var(--dark); }
table.data tr.rowdanger { background: var(--danger-bg); }
table.data tr.rowwarn { background: var(--warn-bg); }
.tfoot { padding: 8px 12px; font-size: 0.8125rem; color: var(--ink-3); display: flex; gap: 10px; align-items: center; }

dl.def { display: grid; grid-template-columns: minmax(130px, max-content) 1fr; gap: 4px 14px; font-size: 0.8125rem; margin: 0; }
dl.def dt { color: var(--ink-3); }
dl.def dd { margin: 0; color: var(--ink); overflow-wrap: anywhere; }
dl.def.stack { grid-template-columns: 1fr; gap: 2px; }
dl.def.stack dd { margin-bottom: 8px; }

.kv { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 0.8125rem; }
.kv > div { display: flex; gap: 6px; }
.kv b { color: var(--ink-3); font-weight: 500; }

/* ---------------------------------------------------------------- chips & badges */
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 1px 7px; border-radius: 10px; font-size: 0.72rem; font-weight: 600;
  background: var(--line-2); color: var(--ink-2); white-space: nowrap; border: 1px solid transparent;
}
.chip.ok { background: var(--ok-bg); color: var(--ok); }
.chip.warn { background: var(--warn-bg); color: var(--warn); }
.chip.danger { background: var(--danger-bg); color: var(--danger); }
.chip.info { background: var(--info-bg); color: var(--info); }
.chip.neutral { background: var(--line-2); color: var(--ink-2); }
.chip.solid-danger { background: var(--danger); color: #fff; }
.chip.p1 { background: var(--danger); color: #fff; }
.chip.p2 { background: #f7dbc9; color: #8a3f0b; }
.chip.p3 { background: var(--info-bg); color: var(--info); }
.chip.p4 { background: var(--line-2); color: var(--ink-2); }
.chip.big { font-size: 0.8125rem; padding: 3px 10px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }

.count { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 1.6rem; color: var(--dark); line-height: 1; }
.count.danger { color: var(--danger); }
.count.warn { color: var(--warn); }
.count.ok { color: var(--ok); }

/* ---------------------------------------------------------------- banners */
.banner { padding: 9px 12px; border-radius: var(--radius); border: 1px solid; font-size: 0.8125rem; margin-bottom: 12px; display: flex; gap: 8px; align-items: flex-start; }
.banner b { display: block; }
.banner.ok { background: var(--ok-bg); border-color: #b6dcc3; color: #14502f; }
.banner.err { background: var(--danger-bg); border-color: #f0b6b3; color: #8d1b18; }
.banner.warn { background: var(--warn-bg); border-color: #edd3a6; color: #6b4100; }
.banner.info { background: var(--info-bg); border-color: #bcd9e8; color: #174c69; }
.banner.security { background: #fff8e8; border-color: #e8cf9a; color: #5e4300; }

.flash { position: sticky; top: 92px; z-index: 20; }

/* ---------------------------------------------------------------- buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: inherit; font-size: 0.8125rem; font-weight: 500;
  padding: 7px 13px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); cursor: pointer; text-decoration: none;
}
.btn:hover { background: var(--surface-2); text-decoration: none; border-color: #c2c7d1; }
.btn:active { transform: translateY(1px); }
.btn.primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-light); border-color: var(--primary-light); }
.btn.accent { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.accent:hover { background: #2f7da2; }
.btn.danger { background: var(--surface); border-color: #e3aeab; color: var(--danger); }
.btn.danger:hover { background: var(--danger-bg); }
.btn.small { font-size: 0.75rem; padding: 3px 8px; min-height: 28px; }
.btn.block { width: 100%; }
.btn:disabled, .btn[aria-disabled='true'] { opacity: 0.5; cursor: not-allowed; }
.btnrow { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.btnrow.end { justify-content: flex-end; }

/* ---------------------------------------------------------------- forms */
form.stack { display: grid; gap: 12px; }
.fields { display: grid; gap: 12px; }
.fields.cols2 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.fields.cols3 { grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); }
.field { display: grid; gap: 4px; min-width: 0; }
.field > label, .field > .lbl { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); }
.field .hint { font-size: 0.75rem; color: var(--ink-3); }
.field .err { font-size: 0.75rem; color: var(--danger); font-weight: 500; }
.field.span2 { grid-column: 1 / -1; }
input[type='text'], input[type='password'], input[type='number'], input[type='date'], input[type='datetime-local'], input[type='time'], input[type='email'], input[type='search'], input[type='file'], select, textarea {
  font: inherit; font-size: 0.875rem;
  padding: 7px 9px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); width: 100%;
}
textarea { min-height: 72px; resize: vertical; line-height: 1.4; }
input:invalid { border-color: #e3aeab; }
.field.bad input, .field.bad select, .field.bad textarea { border-color: var(--danger); background: #fffafa; }
select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%), linear-gradient(135deg, var(--ink-3) 50%, transparent 50%); background-position: calc(100% - 15px) 15px, calc(100% - 10px) 15px; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 28px; }
.check { display: flex; gap: 8px; align-items: flex-start; font-size: 0.8125rem; padding: 3px 0; }
.check input[type='checkbox'], .check input[type='radio'] { width: 18px; height: 18px; margin: 1px 0 0; flex: 0 0 auto; accent-color: var(--primary); }
.check label { cursor: pointer; }
.check .hint { display: block; color: var(--ink-3); font-size: 0.75rem; }
fieldset { border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; }
legend { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); padding: 0 5px; }
.filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; }
.filters .field { min-width: 140px; }
.filters .field.wide { min-width: 260px; flex: 1 1 260px; }

/* disclosure panels used for action forms */
details.drawer { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
details.drawer + details.drawer { margin-top: 8px; }
details.drawer > summary {
  cursor: pointer; padding: 8px 12px; font-size: 0.8125rem; font-weight: 600; color: var(--primary);
  display: flex; align-items: center; gap: 8px; list-style: none; min-height: 38px;
}
details.drawer > summary::-webkit-details-marker { display: none; }
details.drawer > summary::before { content: '▸'; color: var(--ink-3); font-size: 0.8rem; }
details.drawer[open] > summary::before { content: '▾'; }
details.drawer[open] > summary { border-bottom: 1px solid var(--line-2); background: var(--surface-2); }
details.drawer .drawerbody { padding: 12px; }
details.drawer.danger > summary { color: var(--danger); }

.timeline { list-style: none; padding: 0; display: grid; gap: 0; }
.timeline li { display: grid; grid-template-columns: 148px 1fr; gap: 12px; padding: 8px 12px; border-bottom: 1px solid var(--line-2); font-size: 0.8125rem; }
.timeline li:last-child { border-bottom: 0; }
.timeline .when { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.timeline .what b { color: var(--dark); }
.timeline li.superseded .what { text-decoration: line-through; color: var(--ink-3); }
@media (max-width: 620px) { .timeline li { grid-template-columns: 1fr; gap: 2px; } }

.prose { font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.prose.box { background: var(--surface-2); border: 1px solid var(--line-2); border-radius: var(--radius); padding: 9px 11px; }
.empty { padding: 22px 12px; text-align: center; color: var(--ink-3); font-size: 0.8125rem; }
.empty b { display: block; color: var(--ink-2); margin-bottom: 3px; }

/* ---------------------------------------------------------------- schedule board */
.board { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.board table { border-collapse: collapse; width: 100%; min-width: 900px; }
.board th, .board td { border-right: 1px solid var(--line-2); border-bottom: 1px solid var(--line-2); }
.board th { background: var(--surface-2); font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-3); padding: 6px 8px; font-weight: 600; }
.board th.eng { text-align: left; width: 132px; min-width: 132px; position: sticky; left: 0; z-index: 2; }
.board td.eng { position: sticky; left: 0; background: var(--surface); z-index: 1; padding: 6px 8px; font-size: 0.8125rem; font-weight: 600; border-right: 1px solid var(--line); }
.board td.eng small { display: block; font-weight: 400; color: var(--ink-3); }
.board td.slot { padding: 0; position: relative; height: 62px; }
.board .lane { position: relative; height: 100%; }
.slotblock {
  position: absolute; top: 3px; bottom: 3px; border-radius: 4px; padding: 3px 6px; overflow: hidden;
  font-size: 0.72rem; line-height: 1.25; border-left: 3px solid var(--primary); background: #eaf1f8; color: var(--ink);
  box-shadow: 0 1px 2px rgba(0,0,0,0.1); text-decoration: none; display: block;
}
.slotblock:hover { text-decoration: none; box-shadow: var(--shadow-lg); z-index: 5; }
.slotblock b { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slotblock.p1 { border-left-color: var(--danger); background: #fdecea; }
.slotblock.p2 { border-left-color: var(--accent-warm); background: #fdf1e8; }
.slotblock.provisional { background-image: repeating-linear-gradient(45deg, rgba(255,255,255,0.65) 0 6px, transparent 6px 12px); }
.slotblock.submitted { opacity: 0.66; }
.slotblock.cancelled { text-decoration: line-through; opacity: 0.5; }
.weekcell { padding: 4px; vertical-align: top; min-width: 132px; }
.weekcell .slotblock { position: static; margin-bottom: 4px; }
.boardlegend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 0.75rem; color: var(--ink-3); padding: 8px 2px; }

/* ---------------------------------------------------------------- field (mobile) */
.fieldlist { display: grid; gap: 10px; }
.jobcard { display: block; background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--primary); border-radius: var(--radius); padding: 12px; box-shadow: var(--shadow); color: var(--ink); }
.jobcard:hover { text-decoration: none; box-shadow: var(--shadow-lg); }
.jobcard.p1 { border-left-color: var(--danger); }
.jobcard.p2 { border-left-color: var(--accent-warm); }
.jobcard .top { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 4px; }
.jobcard .time { font-weight: 700; font-variant-numeric: tabular-nums; }
.jobcard h3 { font-size: 0.95rem; margin: 2px 0; }
.jobcard .where { font-size: 0.8125rem; color: var(--ink-2); }
.jobcard .sym { font-size: 0.8125rem; color: var(--ink-2); margin-top: 5px; }
.bigactions { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
.bigactions .btn { min-height: 52px; font-size: 0.95rem; font-weight: 600; }
.stepbar { display: flex; gap: 6px; font-size: 0.72rem; color: var(--ink-3); flex-wrap: wrap; margin-bottom: 10px; }
.stepbar span { padding: 2px 8px; border-radius: 10px; background: var(--line-2); }
.stepbar span.done { background: var(--ok-bg); color: var(--ok); font-weight: 600; }
.stepbar span.now { background: var(--primary); color: #fff; font-weight: 600; }

/* AI suggestion panel */
.ai { border: 1px solid #c9dce9; border-radius: var(--radius); background: #f6fafd; margin-bottom: 14px; overflow: hidden; }
.ai > header { background: #e4f0f8; padding: 8px 12px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid #c9dce9; }
.ai > header h3 { font-size: 0.85rem; color: #16506f; }
.ai .body { padding: 12px; }
.ai .suggestion { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.ai .sources { font-size: 0.75rem; color: var(--ink-3); margin-top: 8px; display: flex; gap: 8px; flex-wrap: wrap; }
.ai .note { font-size: 0.75rem; color: #16506f; margin-top: 8px; }
.aibuttons { display: flex; gap: 6px; flex-wrap: wrap; }

/* login */
.loginwrap { min-height: 100vh; display: grid; place-items: center; padding: 20px; background: linear-gradient(160deg, var(--primary) 0%, var(--dark) 100%); }
.loginbox { background: var(--surface); border-radius: 10px; box-shadow: var(--shadow-lg); padding: 26px; width: 100%; max-width: 420px; }
.loginbox .brandrow { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; }
.loginbox .brandrow svg { width: 34px; height: 34px; }
.loginbox h1 { font-size: 1.15rem; }
.demotable { width: 100%; font-size: 0.78rem; border-collapse: collapse; margin-top: 6px; }
.demotable td { padding: 3px 6px; border-bottom: 1px solid var(--line-2); }
.demotable td:first-child { font-family: var(--mono); white-space: nowrap; }

footer.appfoot { padding: 14px 16px; font-size: 0.75rem; color: var(--ink-3); text-align: center; }

/* utility */
.right { text-align: right; }
.nowrap { white-space: nowrap; }
.mono-sm { font-family: var(--mono); font-size: 0.78rem; }
.hidden { display: none !important; }
.mt0 { margin-top: 0; }
.mt1 { margin-top: 8px; }
.mt2 { margin-top: 16px; }
.mb1 { margin-bottom: 8px; }
.strong { font-weight: 600; color: var(--dark); }
.tiny { font-size: 0.75rem; }
.sep { color: var(--line); }

@media (max-width: 700px) {
  main { padding: 10px; }
  .pagehead { gap: 8px; }
  table.data th, table.data td { padding: 6px 8px; }
  dl.def { grid-template-columns: 1fr; gap: 1px; }
  dl.def dd { margin-bottom: 7px; }
  .fields.cols2, .fields.cols3 { grid-template-columns: 1fr; }
  h1 { font-size: 1.15rem; }
}

@media print {
  .topbar, nav.mainnav, .btnrow, details.drawer, footer.appfoot { display: none !important; }
  body { background: #fff; }
  .card { box-shadow: none; break-inside: avoid; }
}

toolUseResult.content:
/* FrostLine operations CRM — dense desktop tables, touch-friendly field views.
   Brand cues (colour, name) taken from the public website; layout is application, not marketing. */

:root {
  --primary: #1a3a5c;
  --primary-light: #2a5a8c;
  --accent: #3a8fb7;
  --accent-warm: #e87c3e;
  --dark: #0f2237;
  --ink: #1a1a2e;
  --ink-2: #4a4a5a;
  --ink-3: #6f6f80;
  --line: #d9dce3;
  --line-2: #eceef2;
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --danger: #b4231f;
  --danger-bg: #fdeceb;
  --warn: #8a5300;
  --warn-bg: #fdf3e3;
  --ok: #1f6b3f;
  --ok-bg: #eaf5ee;
  --info: #1d5c80;
  --info-bg: #e9f3f9;
  --radius: 6px;
  --shadow: 0 1px 2px rgba(15, 34, 55, 0.08), 0 2px 8px rgba(15, 34, 55, 0.06);
  --shadow-lg: 0 8px 28px rgba(15, 34, 55, 0.18);
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }

html { font-size: 16px; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.45;
  font-size: 14px;
}

a { color: var(--primary-light); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3, h4 { line-height: 1.25; font-weight: 600; color: var(--dark); }
h1 { font-size: 1.35rem; }
h2 { font-size: 1.05rem; }
h3 { font-size: 0.95rem; }
h4 { font-size: 0.85rem; }
small { font-size: 0.8125rem; }
code, .mono { font-family: var(--mono); font-size: 0.85em; }

:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

.skip { position: absolute; left: -9999px; top: 0; background: var(--surface); padding: 8px 12px; z-index: 100; }
.skip:focus { left: 8px; top: 8px; }

/* ---------------------------------------------------------------- app frame */
.app { min-height: 100vh; display: flex; flex-direction: column; }

.topbar {
  background: var(--primary);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
  min-height: 52px;
  position: sticky;
  top: 0;
  z-index: 30;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 600; letter-spacing: 0.01em; color: #fff; flex: 0 0 auto; }
.brand:hover { text-decoration: none; }
.brand svg { width: 26px; height: 26px; }
.brand span { font-size: 0.95rem; }
.brand b { font-weight: 700; }
.brand-sub { color: #b9cde0; font-weight: 400; font-size: 0.78rem; display: none; }
@media (min-width: 1100px) { .brand-sub { display: inline; } }

.topsearch { flex: 1 1 auto; max-width: 420px; display: flex; }
.topsearch input {
  width: 100%;
  border: 1px solid rgba(255,255,255,0.28);
  background: rgba(255,255,255,0.14);
  color: #fff;
  padding: 6px 10px;
  border-radius: var(--radius);
  font: inherit;
  font-size: 0.875rem;
}
.topsearch input::placeholder { color: #cfe0ee; }
.topsearch input:focus { background: #fff; color: var(--ink); }
.topsearch input:focus::placeholder { color: var(--ink-3); }

.topright { margin-left: auto; display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.whoami { text-align: right; line-height: 1.2; display: none; }
@media (min-width: 720px) { .whoami { display: block; } }
.whoami b { display: block; font-size: 0.8125rem; }
.whoami small { color: #b9cde0; }
.bell { position: relative; color: #fff; display: inline-flex; align-items: center; padding: 4px; }
.bell .dot {
  position: absolute; top: 0; right: 0;
  background: var(--accent-warm); color: #fff; font-size: 0.65rem; font-weight: 700;
  min-width: 16px; height: 16px; border-radius: 8px; display: grid; place-items: center; padding: 0 3px;
}
.logout { color: #cfe0ee; font-size: 0.8125rem; }

nav.mainnav { background: var(--dark); display: flex; gap: 2px; padding: 0 8px; overflow-x: auto; position: sticky; top: 52px; z-index: 29; scrollbar-width: none; }
nav.mainnav::-webkit-scrollbar { display: none; }
nav.mainnav a {
  color: #cfe0ee; padding: 9px 12px; font-size: 0.8125rem; font-weight: 500; white-space: nowrap;
  border-bottom: 3px solid transparent;
}
nav.mainnav a:hover { color: #fff; text-decoration: none; background: rgba(255,255,255,0.05); }
nav.mainnav a[aria-current='page'] { color: #fff; border-bottom-color: var(--accent); }

main { flex: 1 1 auto; padding: 16px; width: 100%; max-width: 1560px; margin: 0 auto; }
main.narrow { max-width: 820px; }

.pagehead { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 12px; margin-bottom: 14px; }
.pagehead .grow { flex: 1 1 320px; min-width: 0; }
.pagehead h1 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.crumbs { font-size: 0.8125rem; color: var(--ink-3); margin-bottom: 4px; }
.crumbs a { color: var(--ink-2); }
.subtle { color: var(--ink-3); }
.pagehead .actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* ---------------------------------------------------------------- surfaces */
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 14px;
  overflow: hidden;
}
.card > header {
  padding: 9px 12px;
  border-bottom: 1px solid var(--line-2);
  background: var(--surface-2);
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
}
.card > header h2, .card > header h3 { font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-2); }
.card > header .spacer { margin-left: auto; }
.card .body { padding: 12px; }
.card .body.tight { padding: 0; }
.card .foot { padding: 9px 12px; border-top: 1px solid var(--line-2); background: var(--surface-2); }
.definition { font-size: 0.78rem; color: var(--ink-3); padding: 8px 12px; border-top: 1px dashed var(--line); background: var(--surface-2); }

.grid { display: grid; gap: 14px; }
.grid.cols2 { grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); }
.grid.cols3 { grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); }
.grid.split { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
@media (max-width: 1000px) { .grid.split { grid-template-columns: 1fr; } }

/* ---------------------------------------------------------------- tables */
.tablewrap { overflow-x: auto; }
table.data { width: 100%; border-collapse: collapse; font-size: 0.8125rem; }
table.data th, table.data td { text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line-2); vertical-align: top; }
table.data th {
  font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--ink-3);
  background: var(--surface-2); position: sticky; top: 0; font-weight: 600; white-space: nowrap;
}
table.data tbody tr:hover { background: #f7fafd; }
table.data tr.clickable { cursor: pointer; }
table.data td.num, table.data th.num { text-align: right; font-variant-numeric: tabular-nums; }
table.data td.nowrap, table.data th.nowrap { white-space: nowrap; }
table.data .rowtitle { font-weight: 600; color: var(--dark); }
table.data tr.rowdanger { background: var(--danger-bg); }
table.data tr.rowwarn { background: var(--warn-bg); }
.tfoot { padding: 8px 12px; font-size: 0.8125rem; color: var(--ink-3); display: flex; gap: 10px; align-items: center; }

dl.def { display: grid; grid-template-columns: minmax(130px, max-content) 1fr; gap: 4px 14px; font-size: 0.8125rem; margin: 0; }
dl.def dt { color: var(--ink-3); }
dl.def dd { margin: 0; color: var(--ink); overflow-wrap: anywhere; }
dl.def.stack { grid-template-columns: 1fr; gap: 2px; }
dl.def.stack dd { margin-bottom: 8px; }

.kv { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 0.8125rem; }
.kv > div { display: flex; gap: 6px; }
.kv b { color: var(--ink-3); font-weight: 500; }

/* ---------------------------------------------------------------- chips & badges */
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 1px 7px; border-radius: 10px; font-size: 0.72rem; font-weight: 600;
  background: var(--line-2); color: var(--ink-2); white-space: nowrap; border: 1px solid transparent;
}
.chip.ok { background: var(--ok-bg); color: var(--ok); }
.chip.warn { background: var(--warn-bg); color: var(--warn); }
.chip.danger { background: var(--danger-bg); color: var(--danger); }
.chip.info { background: var(--info-bg); color: var(--info); }
.chip.neutral { background: var(--line-2); color: var(--ink-2); }
.chip.solid-danger { background: var(--danger); color: #fff; }
.chip.p1 { background: var(--danger); color: #fff; }
.chip.p2 { background: #f7dbc9; color: #8a3f0b; }
.chip.p3 { background: var(--info-bg); color: var(--info); }
.chip.p4 { background: var(--line-2); color: var(--ink-2); }
.chip.big { font-size: 0.8125rem; padding: 3px 10px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }

.count { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 1.6rem; color: var(--dark); line-height: 1; }
.count.danger { color: var(--danger); }
.count.warn { color: var(--warn); }
.count.ok { color: var(--ok); }

/* ---------------------------------------------------------------- banners */
.banner { padding: 9px 12px; border-radius: var(--radius); border: 1px solid; font-size: 0.8125rem; margin-bottom: 12px; display: flex; gap: 8px; align-items: flex-start; }
.banner b { display: block; }
.banner.ok { background: var(--ok-bg); border-color: #b6dcc3; color: #14502f; }
.banner.err { background: var(--danger-bg); border-color: #f0b6b3; color: #8d1b18; }
.banner.warn { background: var(--warn-bg); border-color: #edd3a6; color: #6b4100; }
.banner.info { background: var(--info-bg); border-color: #bcd9e8; color: #174c69; }
.banner.security { background: #fff8e8; border-color: #e8cf9a; color: #5e4300; }

.flash { position: sticky; top: 92px; z-index: 20; }

/* ---------------------------------------------------------------- buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  font: inherit; font-size: 0.8125rem; font-weight: 500;
  padding: 7px 13px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); cursor: pointer; text-decoration: none;
}
.btn:hover { background: var(--surface-2); text-decoration: none; border-color: #c2c7d1; }
.btn:active { transform: translateY(1px); }
.btn.primary { background: var(--primary); border-color: var(--primary); color: #fff; }
.btn.primary:hover { background: var(--primary-light); border-color: var(--primary-light); }
.btn.accent { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn.accent:hover { background: #2f7da2; }
.btn.danger { background: var(--surface); border-color: #e3aeab; color: var(--danger); }
.btn.danger:hover { background: var(--danger-bg); }
.btn.small { font-size: 0.75rem; padding: 3px 8px; min-height: 28px; }
.btn.block { width: 100%; }
.btn:disabled, .btn[aria-disabled='true'] { opacity: 0.5; cursor: not-allowed; }
.btnrow { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.btnrow.end { justify-content: flex-end; }

/* ---------------------------------------------------------------- forms */
form.stack { display: grid; gap: 12px; }
.fields { display: grid; gap: 12px; }
.fields.cols2 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.fields.cols3 { grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); }
.field { display: grid; gap: 4px; min-width: 0; }
.field > label, .field > .lbl { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); }
.field .hint { font-size: 0.75rem; color: var(--ink-3); }
.field .err { font-size: 0.75rem; color: var(--danger); font-weight: 500; }
.field.span2 { grid-column: 1 / -1; }
input[type='text'], input[type='password'], input[type='number'], input[type='date'], input[type='datetime-local'], input[type='time'], input[type='email'], input[type='search'], input[type='file'], select, textarea {
  font: inherit; font-size: 0.875rem;
  padding: 7px 9px; min-height: 36px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); color: var(--ink); width: 100%;
}
textarea { min-height: 72px; resize: vertical; line-height: 1.4; }
input:invalid { border-color: #e3aeab; }
.field.bad input, .field.bad select, .field.bad textarea { border-color: var(--danger); background: #fffafa; }
select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%), linear-gradient(135deg, var(--ink-3) 50%, transparent 50%); background-position: calc(100% - 15px) 15px, calc(100% - 10px) 15px; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 28px; }
.check { display: flex; gap: 8px; align-items: flex-start; font-size: 0.8125rem; padding: 3px 0; }
.check input[type='checkbox'], .check input[type='radio'] { width: 18px; height: 18px; margin: 1px 0 0; flex: 0 0 auto; accent-color: var(--primary); }
.check label { cursor: pointer; }
.check .hint { display: block; color: var(--ink-3); font-size: 0.75rem; }
fieldset { border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; }
legend { font-size: 0.78rem; font-weight: 600; color: var(--ink-2); padding: 0 5px; }
.filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; }
.filters .field { min-width: 140px; }
.filters .field.wide { min-width: 260px; flex: 1 1 260px; }

/* disclosure panels used for action forms */
details.drawer { border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
details.drawer + details.drawer { margin-top: 8px; }
details.drawer > summary {
  cursor: pointer; padding: 8px 12px; font-size: 0.8125rem; font-weight: 600; color: var(--primary);
  display: flex; align-items: center; gap: 8px; list-style: none; min-height: 38px;
}
details.drawer > summary::-webkit-details-marker { display: none; }
details.drawer > summary::before { content: '▸'; color: var(--ink-3); font-size: 0.8rem; }
details.drawer[open] > summary::before { content: '▾'; }
details.drawer[open] > summary { border-bottom: 1px solid var(--line-2); background: var(--surface-2); }
details.drawer .drawerbody { padding: 12px; }
details.drawer.danger > summary { color: var(--danger); }

.timeline { list-style: none; padding: 0; display: grid; gap: 0; }
.timeline li { display: grid; grid-template-columns: 148px 1fr; gap: 12px; padding: 8px 12px; border-bottom: 1px solid var(--line-2); font-size: 0.8125rem; }
.timeline li:last-child { border-bottom: 0; }
.timeline .when { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.timeline .what b { color: var(--dark); }
.timeline li.superseded .what { text-decoration: line-through; color: var(--ink-3); }
@media (max-width: 620px) { .timeline li { grid-template-columns: 1fr; gap: 2px; } }

.prose { font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.prose.box { background: var(--surface-2); border: 1px solid var(--line-2); border-radius: var(--radius); padding: 9px 11px; }
.empty { padding: 22px 12px; text-align: center; color: var(--ink-3); font-size: 0.8125rem; }
.empty b { display: block; color: var(--ink-2); margin-bottom: 3px; }

/* ---------------------------------------------------------------- schedule board */
.board { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.board table { border-collapse: collapse; width: 100%; min-width: 900px; }
.board th, .board td { border-right: 1px solid var(--line-2); border-bottom: 1px solid var(--line-2); }
.board th { background: var(--surface-2); font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--ink-3); padding: 6px 8px; font-weight: 600; }
.board th.eng { text-align: left; width: 132px; min-width: 132px; position: sticky; left: 0; z-index: 2; }
.board td.eng { position: sticky; left: 0; background: var(--surface); z-index: 1; padding: 6px 8px; font-size: 0.8125rem; font-weight: 600; border-right: 1px solid var(--line); }
.board td.eng small { display: block; font-weight: 400; color: var(--ink-3); }
.board td.slot { padding: 0; position: relative; height: 62px; }
.board .lane { position: relative; height: 100%; }
.slotblock {
  position: absolute; top: 3px; bottom: 3px; border-radius: 4px; padding: 3px 6px; overflow: hidden;
  font-size: 0.72rem; line-height: 1.25; border-left: 3px solid var(--primary); background: #eaf1f8; color: var(--ink);
  box-shadow: 0 1px 2px rgba(0,0,0,0.1); text-decoration: none; display: block;
}
.slotblock:hover { text-decoration: none; box-shadow: var(--shadow-lg); z-index: 5; }
.slotblock b { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.slotblock.p1 { border-left-color: var(--danger); background: #fdecea; }
.slotblock.p2 { border-left-color: var(--accent-warm); background: #fdf1e8; }
.slotblock.provisional { background-image: repeating-linear-gradient(45deg, rgba(255,255,255,0.65) 0 6px, transparent 6px 12px); }
.slotblock.submitted { opacity: 0.66; }
.slotblock.cancelled { text-decoration: line-through; opacity: 0.5; }
.weekcell { padding: 4px; vertical-align: top; min-width: 132px; }
.weekcell .slotblock { position: static; margin-bottom: 4px; }
.boardlegend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 0.75rem; color: var(--ink-3); padding: 8px 2px; }

/* ---------------------------------------------------------------- field (mobile) */
.fieldlist { display: grid; gap: 10px; }
.jobcard { display: block; background: var(--surface); border: 1px solid var(--line); border-left: 4px solid var(--primary); border-radius: var(--radius); padding: 12px; box-shadow: var(--shadow); color: var(--ink); }
.jobcard:hover { text-decoration: none; box-shadow: var(--shadow-lg); }
.jobcard.p1 { border-left-color: var(--danger); }
.jobcard.p2 { border-left-color: var(--accent-warm); }
.jobcard .top { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 4px; }
.jobcard .time { font-weight: 700; font-variant-numeric: tabular-nums; }
.jobcard h3 { font-size: 0.95rem; margin: 2px 0; }
.jobcard .where { font-size: 0.8125rem; color: var(--ink-2); }
.jobcard .sym { font-size: 0.8125rem; color: var(--ink-2); margin-top: 5px; }
.bigactions { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
.bigactions .btn { min-height: 52px; font-size: 0.95rem; font-weight: 600; }
.stepbar { display: flex; gap: 6px; font-size: 0.72rem; color: var(--ink-3); flex-wrap: wrap; margin-bottom: 10px; }
.stepbar span { padding: 2px 8px; border-radius: 10px; background: var(--line-2); }
.stepbar span.done { background: var(--ok-bg); color: var(--ok); font-weight: 600; }
.stepbar span.now { background: var(--primary); color: #fff; font-weight: 600; }

/* AI suggestion panel */
.ai { border: 1px solid #c9dce9; border-radius: var(--radius); background: #f6fafd; margin-bottom: 14px; overflow: hidden; }
.ai > header { background: #e4f0f8; padding: 8px 12px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; border-bottom: 1px solid #c9dce9; }
.ai > header h3 { font-size: 0.85rem; color: #16506f; }
.ai .body { padding: 12px; }
.ai .suggestion { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; font-size: 0.8125rem; white-space: pre-wrap; overflow-wrap: anywhere; }
.ai .sources { font-size: 0.75rem; color: var(--ink-3); margin-top: 8px; display: flex; gap: 8px; flex-wrap: wrap; }
.ai .note { font-size: 0.75rem; color: #16506f; margin-top: 8px; }
.aibuttons { display: flex; gap: 6px; flex-wrap: wrap; }

/* login */
.loginwrap { min-height: 100vh; display: grid; place-items: center; padding: 20px; background: linear-gradient(160deg, var(--primary) 0%, var(--dark) 100%); }
.loginbox { background: var(--surface); border-radius: 10px; box-shadow: var(--shadow-lg); padding: 26px; width: 100%; max-width: 420px; }
.loginbox .brandrow { display: flex; align-items: center; gap: 10px; margin-bottom: 4px; }
.loginbox .brandrow svg { width: 34px; height: 34px; }
.loginbox h1 { font-size: 1.15rem; }
.demotable { width: 100%; font-size: 0.78rem; border-collapse: collapse; margin-top: 6px; }
.demotable td { padding: 3px 6px; border-bottom: 1px solid var(--line-2); }
.demotable td:first-child { font-family: var(--mono); white-space: nowrap; }

footer.appfoot { padding: 14px 16px; font-size: 0.75rem; color: var(--ink-3); text-align: center; }

/* utility */
.right { text-align: right; }
.nowrap { white-space: nowrap; }
.mono-sm { font-family: var(--mono); font-size: 0.78rem; }
.hidden { display: none !important; }
.mt0 { margin-top: 0; }
.mt1 { margin-top: 8px; }
.mt2 { margin-top: 16px; }
.mb1 { margin-bottom: 8px; }
.strong { font-weight: 600; color: var(--dark); }
.tiny { font-size: 0.75rem; }
.sep { color: var(--line); }

@media (max-width: 700px) {
  main { padding: 10px; }
  .pagehead { gap: 8px; }
  table.data th, table.data td { padding: 6px 8px; }
  dl.def { grid-template-columns: 1fr; gap: 1px; }
  dl.def dd { margin-bottom: 7px; }
  .fields.cols2, .fields.cols3 { grid-template-columns: 1fr; }
  h1 { font-size: 1.15rem; }
}

@media print {
  .topbar, nav.mainnav, .btnrow, details.drawer, footer.appfoot { display: none !important; }
  body { background: #fff; }
  .card { box-shadow: none; break-inside: avoid; }
}

