import crypto from 'node:crypto';
import path from 'node:path';
import express, { type NextFunction, type Request, type Response } from 'express';
import type { DB } from '../db/db.ts';
import { openDb } from '../db/db.ts';
import { config } from '../config.ts';
import { type Capability, can, type Role, requireCap as policyRequireCap, ROLE_LABEL } from '../auth/policy.ts';
import { login as doLogin, logout as doLogout, type SessionUser, sessionUser } from '../auth/auth.ts';
import { DomainError, ForbiddenError, NotFoundError } from '../lib/errors.ts';
import { requestContext } from '../lib/context.ts';
import { escapeHtml, html, raw } from '../lib/html.ts';
import { unreadCount } from '../domain/admin.ts';
import { AiAssistant, type AiProvider, providerFromEnv } from '../ai/assistant.ts';
import { banner, type Ctx, loginPage, page } from './ui.ts';

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      user?: SessionUser;
      ctx?: Ctx;
    }
  }
}

export interface AppDeps {
  db: DB;
  /** Read-only connection handed to the AI assistant (ADR-006 boundary). */
  readDb?: DB;
  provider?: AiProvider;
  uploadDir?: string;
}

const PUBLIC_PATHS = new Set(['/login', '/healthz']);

export function createApp(deps: AppDeps) {
  const { db } = deps;
  const uploadDir = deps.uploadDir ?? config.uploadDir;
  const readDb = deps.readDb ?? db;
  const ai = new AiAssistant(readDb, db, deps.provider ?? providerFromEnv());

  const app = express();
  app.disable('x-powered-by');
  app.set('trust proxy', 1);

  app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('Referrer-Policy', 'same-origin');
    res.setHeader(
      'Content-Security-Policy',
      "default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'",
    );
    requestContext.run({ correlationId: crypto.randomUUID() }, () => next());
  });

  app.use('/static', express.static(path.join(config.root, 'public'), { maxAge: config.isProd ? '1h' : 0, index: false }));
  app.use(express.urlencoded({ extended: true, limit: '1mb' }));
  app.use(express.json({ limit: '256kb' }));

  app.get('/healthz', (_req, res) => {
    const row = db.prepare('SELECT COUNT(*) n FROM users').get() as { n: number };
    res.json({ status: 'ok', users: row.n, time: new Date().toISOString() });
  });

  // ---------------------------------------------------------------- session & CSRF
  app.use((req, _res, next) => {
    req.user = sessionUser(db, readCookie(req, config.sessionCookie)) ?? undefined;
    next();
  });

  app.get('/login', (req, res) => {
    if (req.user) return res.redirect('/');
    const users = db.prepare(`SELECT username, display_name, role FROM users WHERE active = 1 ORDER BY role, display_name`).all() as { username: string; display_name: string; role: Role }[];
    const csrf = ensureLoginToken(req, res);
    res.type('html').send(loginPage({ users, csrf, next: typeof req.query.next === 'string' ? req.query.next : undefined, error: flashOf(req, res)?.message }));
  });

  app.post('/login', (req, res) => {
    const token = readCookie(req, 'frostline_lt');
    if (!token || !safeEqual(token, String(req.body?._csrf ?? ''))) {
      setFlash(res, 'err', 'Your sign-in form expired. Please try again.');
      return res.redirect('/login');
    }
    const session = doLogin(db, String(req.body?.username ?? ''), String(req.body?.password ?? ''));
    if (!session) {
      setFlash(res, 'err', 'Username or password not recognised.');
      return res.redirect('/login');
    }
    res.cookie(config.sessionCookie, session.sessionId, { httpOnly: true, sameSite: 'lax', secure: config.isProd, path: '/' });
    res.clearCookie('frostline_lt', { path: '/' });
    const next = typeof req.body?.next === 'string' && req.body.next.startsWith('/') ? req.body.next : '/';
    res.redirect(next);
  });

  app.use((req, res, next) => {
    if (PUBLIC_PATHS.has(req.path)) return next();
    if (!req.user) {
      if (req.method !== 'GET') {
        setFlash(res, 'err', 'Your session ended. Please sign in again.');
        return res.redirect('/login');
      }
      return res.redirect(`/login?next=${encodeURIComponent(req.originalUrl)}`);
    }
    req.ctx = { user: req.user, csrf: req.user.csrf, path: req.path, unread: unreadCount(db, req.user.id), flash: flashOf(req, res) };
    next();
  });

  // CSRF for every state-changing request (ADR: authorise actions, not just pages).
  app.use((req, res, next) => {
    if (req.method === 'GET' || req.method === 'HEAD') return next();
    if (req.path === '/login') return next();
    const supplied = String((req.body as Record<string, unknown> | undefined)?._csrf ?? req.get('x-csrf-token') ?? '');
    if (!req.user || !safeEqual(req.user.csrf, supplied)) {
      setFlash(res, 'err', 'That form expired or came from another tab. Please reload the page and try again.');
      return res.redirect(back(req));
    }
    next();
  });

  app.post('/logout', (req, res) => {
    if (req.user) doLogout(db, req.user.sessionId);
    res.clearCookie(config.sessionCookie, { path: '/' });
    setFlash(res, 'ok', 'Signed out.');
    res.redirect('/login');
  });

  // ---------------------------------------------------------------- routes
  const deps2: RouteDeps = { db, readDb, ai, uploadDir };
  for (const register of ROUTES) register(app, deps2);

  // ---------------------------------------------------------------- errors
  app.use((req, res) => {
    if (!req.ctx) return res.status(404).type('text').send('Not found');
    res.status(404).type('html').send(
      page(req.ctx, {
        title: 'Not found',
        heading: 'Page not found',
        narrow: true,
        body: html`${banner('warn', html`No page at <code>${req.path}</code>. It may have moved, or the record may have been removed.`)}<a class="btn" href="/">Back to dashboard</a>`,
      }),
    );
  });

  app.use((err: Error, req: Request, res: Response, _next: NextFunction) => {
    const de = err as DomainError;
    const status = typeof de.status === 'number' ? de.status : 500;
    const isDomain = err instanceof DomainError;
    if (!isDomain || status >= 500) {
      console.error(JSON.stringify({ level: 'error', msg: err.message, stack: err.stack?.split('\n').slice(0, 4), path: req.originalUrl, method: req.method, user: req.user?.username }));
    }
    // Non-GET failures return the user to the page they submitted from, with the reason.
    if (req.method !== 'GET' && isDomain) {
      setFlash(res, 'err', err.message);
      return res.redirect(back(req));
    }
    if (!req.ctx) return res.status(status).type('text').send(isDomain ? err.message : 'Something went wrong.');
    res.status(status).type('html').send(
      page(req.ctx, {
        title: status === 403 ? 'Not permitted' : status === 404 ? 'Not found' : 'Something went wrong',
        heading: status === 403 ? 'Not permitted' : status === 404 ? 'Not found' : 'Something went wrong',
        narrow: true,
        body: html`${banner(
          status === 500 ? 'err' : 'warn',
          isDomain
            ? html`${err.message}`
            : html`The page could not be built. Nothing was changed. If it keeps happening, quote this reference to support: <code>${requestContext.getStore()?.correlationId ?? '—'}</code>.`,
        )}
        ${status === 403 ? html`<p class="subtle">You are signed in as ${req.user?.name} (${ROLE_LABEL[req.user!.role]}).</p>` : ''}
        <div class="btnrow"><a class="btn" href="/">Dashboard</a><a class="btn" href="javascript:history.back()">Go back</a></div>`,
      }),
    );
  });

  return app;
}

// ---------------------------------------------------------------- route plumbing shared with route modules

export interface RouteDeps {
  db: DB;
  readDb: DB;
  ai: AiAssistant;
  uploadDir: string;
}
export type RouteModule = (app: express.Express, deps: RouteDeps) => void;

const ROUTES: RouteModule[] = [];
export function useRoutes(...mods: RouteModule[]) {
  ROUTES.push(...mods);
}

export function ctxOf(req: Request): Ctx {
  if (!req.ctx) throw new ForbiddenError('Sign in required.');
  return req.ctx;
}

export function actorOf(req: Request): SessionUser {
  if (!req.user) throw new ForbiddenError('Sign in required.');
  return req.user;
}

export function needCap(req: Request, cap: Capability): SessionUser {
  const user = actorOf(req);
  policyRequireCap(user, cap);
  return user;
}

export function canReq(req: Request, cap: Capability): boolean {
  return can(req.user, cap);
}

export function intParam(req: Request, name = 'id'): number {
  const v = parseInt(String(req.params[name]), 10);
  if (!Number.isInteger(v) || v <= 0) throw new NotFoundError();
  return v;
}

export function intQuery(req: Request, name: string): number | undefined {
  const raw = req.query[name];
  if (raw === undefined || raw === '') return undefined;
  const v = parseInt(String(raw), 10);
  return Number.isInteger(v) ? v : undefined;
}

export function strQuery(req: Request, name: string, max = 200): string | undefined {
  const v = req.query[name];
  if (typeof v !== 'string' || v === '') return undefined;
  return v.slice(0, max);
}

export function send(res: Response, body: string) {
  res.type('html').send(body);
}

/** Where a form submission should return to. Only same-site paths are honoured. */
export function back(req: Request): string {
  const supplied = (req.body as Record<string, unknown> | undefined)?.__back;
  if (typeof supplied === 'string' && supplied.startsWith('/') && !supplied.startsWith('//')) return supplied;
  const ref = req.get('referer');
  if (ref) {
    try {
      const u = new URL(ref, `${req.protocol}://${req.get('host')}`);
      if (u.host === req.get('host')) return u.pathname + u.search + u.hash;
    } catch {
      /* ignore */
    }
  }
  return '/';
}

export function redirectWithFlash(res: Response, to: string, tone: 'ok' | 'err' | 'warn' | 'info', message: string) {
  setFlash(res, tone, message);
  res.redirect(to);
}

export function ok(res: Response, to: string, message: string) {
  redirectWithFlash(res, to, 'ok', message);
}

export function setFlash(res: Response, tone: 'ok' | 'err' | 'warn' | 'info', message: string) {
  const payload = Buffer.from(JSON.stringify({ tone, message: message.slice(0, 400) }), 'utf8').toString('base64url');
  res.cookie('frostline_flash', payload, { httpOnly: true, sameSite: 'lax', secure: config.isProd, path: '/', maxAge: 30_000 });
}

function flashOf(req: Request, res: Response): Ctx['flash'] {
  const raw = readCookie(req, 'frostline_flash');
  if (!raw) return null;
  res.clearCookie('frostline_flash', { path: '/' });
  try {
    const parsed = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8')) as { tone: string; message: string };
    const tone = ['ok', 'err', 'warn', 'info'].includes(parsed.tone) ? (parsed.tone as 'ok') : 'info';
    return { tone, message: String(parsed.message).slice(0, 400) };
  } catch {
    return null;
  }
}

function ensureLoginToken(req: Request, res: Response): string {
  const existing = readCookie(req, 'frostline_lt');
  if (existing) return existing;
  const token = crypto.randomBytes(24).toString('base64url');
  res.cookie('frostline_lt', token, { httpOnly: true, sameSite: 'lax', secure: config.isProd, path: '/', maxAge: 30 * 60_000 });
  return token;
}

function readCookie(req: Request, name: string): string | undefined {
  const header = req.get('cookie');
  if (!header) return undefined;
  for (const part of header.split(';')) {
    const idx = part.indexOf('=');
    if (idx < 0) continue;
    if (part.slice(0, idx).trim() === name) return decodeURIComponent(part.slice(idx + 1).trim());
  }
  return undefined;
}

function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(String(a));
  const bb = Buffer.from(String(b));
  if (ab.length !== bb.length || ab.length === 0) return false;
  return crypto.timingSafeEqual(ab, bb);
}

/** Hidden input recording where a form was submitted from, so errors return there. */
export function backInput(req: Request) {
  return html`<input type="hidden" name="__back" value="${escapeHtml(req.originalUrl)}">`;
}

export { escapeHtml, html, raw };

/** Opens the read-only companion connection used for AI context. */
export function openReadOnly(file: string): DB | undefined {
  try {
    return openDb(file, { readonly: true });
  } catch (err) {
    console.error(JSON.stringify({ level: 'warn', msg: 'read-only connection unavailable; AI context will use the main connection', error: (err as Error).message }));
    return undefined;
  }
}

