  // ---------------------------------------------------------------- contacts
  app.get(
    '/customers/:id/contacts/new',
    h((req, res) => {
      needCap(req, 'crm.write');
      const ctx = ctxOf(req);
      const customer = CRM.getCustomer(db, intParam(req));
      const sites = CRM.sitesForCustomer(db, customer.id);
      send(
        res,
        page(ctx, {
          title: 'Add contact',
          heading: `Add contact — ${customer.trading_name}`,
