  );

  app.get(
    '/sites/:id/assets/new',
    h((req, res) => {
      needCap(req, 'crm.write');
      const ctx = ctxOf(req);
      const site = CRM.getSite(db, intParam(req));
      send(
        res,
        page(ctx, {
          title: 'Add equipment',
          heading: `Add equipment — ${site.name}`,
          narrow: true,
          crumbs: [{ href: `/sites/${site.id}`, label: site.name }, { label: 'New equipment' }],
          body: assetForm(ctx, site.id, null),
        }),
      );
