                body: table({ cols: ['Type', { label: 'Jobs', num: true }], rows: [...byKind.entries()].map(([k, n]) => [labelise(k), String(n)]), empty: 'None.' }),
                definition: `Same population as above, grouped by job type.`,
              })}
              ${card({
                title: 'Contractual SLA outcomes',
                tight: true,
                body: table({
