                          ${select({ name: 'code', label: 'Code', required: true, options: codes.map((c) => ({ value: c.code, label: `${c.code} — ${c.label}` })) })}
                          ${input({ name: 'label', label: 'Label shown to engineers', required: true })}
                        </div>
