                })}
              </div>
              <div>
                ${card({
                  title: 'Settings',
                  tight: true,
                  body: html`${table({
                    cols: ['Setting', 'Value'],
                    rows: settings.map((s) => [html`${Admin.EDITABLE_SETTINGS[s.key] ?? s.key}<br><span class="tiny subtle mono-sm">${s.key}</span>`, html`<b>${s.value}</b>`]),
