              </div>
            </div>
          `,
        }),
      );
    }),
  );

  app.get(
    '/admin/users/new',
    h((req, res) => {
      needCap(req, 'admin.users');
      const ctx = ctxOf(req);
      send(res, page(ctx, { title: 'Add person', heading: 'Add person', narrow: true, crumbs: [{ href: '/admin', label: 'Administration' }, { label: 'New' }], body: userForm(ctx, null, Inv.locations(db)) }));
    }),
  );

  app.get(
