  app.post(
    '/admin/policies',
    h((req, res) => {
      Admin.savePolicy(db, actorOf(req), req.body);
      ok(res, back(req), 'Approval policy updated.');
    }),
  );
  app.post(
    '/admin/settings',
    h((req, res) => {
      Admin.saveSetting(db, actorOf(req), req.body);
      ok(res, back(req), 'Setting saved.');
    }),
  );
  app.post(
    '/admin/outcome-codes',
    h((req, res) => {
      Admin.saveOutcomeCode(db, actorOf(req), req.body);
