"""/**
 * Test attendances are booked well clear of the seeded diary so a clash only happens when a
 * test deliberately creates one. Each call takes the next free window.
 */
let slotSeq = 0;
function freeSlot(): { start: string; end: string } {
  slotSeq += 1;
  const base = 30 * 24 * 60 + slotSeq * 4 * 60; // a month out, 4 hours apart
  return { start: localIn(base), end: localIn(base + 120) };
}

/** Creates a fresh reactive job at a covered site, ready to schedule. */""")

# Replace all planned_start/planned_end pairs that used localIn(...) with a per-test free slot.
s = re.sub(r"planned_start: localIn\(\d+\),\n(\s*)planned_end: localIn\(\d+\),", lambda m: f"planned_start: slot.start,\n{m.group(1)}planned_end: slot.end,", s)

# Insert `const slot = freeSlot();` at the start of each test body that uses slot.
out_lines = []
for block in s.split("\n"):
    out_lines.append(block)
s = "\n".join(out_lines)

# For each `it(...)` arrow body containing 'slot.start', insert the const after the first line of the body.
def add_slot(match):
    body = match.group(0)
    if 'slot.start' in body and 'const slot = freeSlot();' not in body:
        # insert after the first '{' line
        idx = body.index('\n')
        return body[:idx+1] + "    const slot = freeSlot();\n" + body[idx+1:]
    return body
s = re.sub(r"it\('[^']*', \(\) => \{.*?\n  \}\);", add_slot, s, flags=re.S)

# 2. Acknowledged is not recorded unless intake says so.
s = s.replace("""    assert.deepEqual(
      events.map((e) => e.type),
      ['received', 'acknowledged', 'response'],
      'received, acknowledged and response are separate events',
    );""",
"""    assert.deepEqual(events.map((e) => e.type), ['received', 'response'], 'received and response are separate events');
    S.recordManualEvent(db, actors.dan, id, { type: 'acknowledged', note: 'Confirmed to the customer' });
    assert.deepEqual(
      S.slaEvents(db, id).filter((e) => !e.superseded).map((e) => e.type).sort(),
      ['acknowledged', 'received', 'response'],
      'acknowledgement is its own event, not a byproduct of another',
    );""")

# 3. Use an unmistakably different timestamp so the update is never a no-op.
s = s.replace("""assert.throws(() => db.prepare(`UPDATE sla_events SET occurred_at = ? WHERE id = ?`).run(new Date().toISOString(), event.id), /append-only/, 'timestamps cannot be rewritten in place');""",
"""assert.throws(() => db.prepare(`UPDATE sla_events SET occurred_at = ? WHERE id = ?`).run('2020-01-01T00:00:00.000Z', event.id), /append-only/, 'timestamps cannot be rewritten in place');""")

# 4. The late-entry test needs a job that was received earlier than the event being recorded.
s = s.replace("""  it('requires an explanation for a late manual entry', () => {
    const { db, actors } = env;
    const id = newReadyJob();""",
"""  it('requires an explanation for a late manual entry', () => {
    const { db, actors } = env;
    const site = one<{ id: number }>(db, `SELECT id FROM sites WHERE name = 'Oakwood Lodge'`);
    const id = J.createJob(db, actors.dan, {
      site_id: String(site.id),
